import * as THREE from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} [position]
 * @property {{x:number,y:number,z:number}} [rotation]
 * @property {{x:number,y:number,z:number}} [scale]
 * @property {string[]} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {{[key:string]: Function}} primitives
 * @property {{getTexture:(text:string, opts:any)=>THREE.Texture}} fontAtlas
 */

/**
 * Create a 3x2 wall of machined‑metal tiles with monochrome brand‑mark text.
 */
export default function createNode(config, ctx) {
  const container = new THREE.Object3D();

  // apply transform from config (fallback to defaults)
  if (config.position) container.position.set(config.position.x, config.position.y, config.position.z);
  if (config.rotation) container.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  if (config.scale) container.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // ----- grid parameters -----
  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const cols = 3;
  const rows = 2;
  const totalW = cols * tileW + (cols - 1) * gap; // 3.5
  const totalH = rows * tileH + (rows - 1) * gap; // 1.49
  const startX = -totalW / 2 + tileW / 2; // -1.25
  const startY = totalH / 2 - tileH / 2; // +0.435

  // brand‑mark texts order (top‑left → bottom‑right)
  const brandTexts = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES',
  ];

  const tiles = [];
  const cleanupResources = [];

  // helper to create a rounded‑rect shape geometry (chamfer 0.02)
  const createRoundedPlane = (w, h, r) => {
    const shape = new THREE.Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    shape.closePath();
    return new THREE.ShapeGeometry(shape);
  };

  // create each tile
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const idx = row * cols + col;
      const tile = new THREE.Mesh(
        createRoundedPlane(tileW, tileH, 0.02),
        new THREE.MeshStandardNodeMaterial()
      );

      // position in grid
      tile.position.set(
        startX + col * (tileW + gap),
        startY - row * (tileH + gap),
        0
      );

      // ----- material node setup (vertical gradient) -----
      const mat = /** @type {THREE.MeshStandardNodeMaterial} */ (tile.material);
      // base color gradient via node graph
      const gradColor = mix(
        color('#1a1a22'),
        color('#121218'),
        uv().y
      );
      mat.colorNode = gradColor;
      // PBR properties per spec
      mat.metalness = 0.5;
      mat.roughness = 0.55;
      mat.clearcoat = 0.2;
      mat.anisotropy = 0.6; // aligns to X by default (rotation 0)
      mat.transparent = true;
      mat.opacity = 0; // start invisible for staggered fade‑up
      // ensure we get clearcoat reflections
      mat.clearcoatRoughness = 0.1;

      // ----- create brand‑mark text mesh -----
      const txt = brandTexts[idx];
      const txtTex = ctx.fontAtlas.getTexture(txt, {
        family: 'JetBrains Mono',
        fontSize: 13,
        fontWeight: 700,
        color: '#e8ecf2',
        opacity: 0.78,
        atlas: 0,
        rect: [0, 0, 512, 320],
        letterSpacing: 0.08,
        lineHeight: 1,
      });

      // estimate text plane size (scale to fit inside tile)
      const txtPlaneW = tileW * 0.8;
      const txtPlaneH = tileH * 0.3;

      const txtGeo = new THREE.PlaneGeometry(txtPlaneW, txtPlaneH);
      const txtMat = new THREE.MeshBasicNodeMaterial();
      txtMat.map = txtTex;
      txtMat.transparent = true;
      txtMat.opacity = 0.78; // start at final opacity (will be animated on hover)
      const txtMesh = new THREE.Mesh(txtGeo, txtMat);
      txtMesh.position.set(0, 0, 0.001); // slightly in front of tile surface
      tile.add(txtMesh);

      // ----- hover interaction (opacity + translateZ) -----
      const hoverTl = gsap.timeline({ paused: true });
      hoverTl
        .to(
          tile.position,
          { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
          0
        )
        .to(
          txtMat,
          { opacity: 1.0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
          0
        );

      tile.userData.handlers = {
        pointerenter: () => {
          hoverTl.play(0);
        },
        pointerleave: () => {
          hoverTl.reverse();
        },
      };
      tile.userData._hoverTL = hoverTl;

      container.add(tile);
      tiles.push({ tile, txtMat });
      cleanupResources.push(tile.geometry, mat, txtGeo, txtMat, txtTex);
    }
  }

  // ----- kicker text ("AS FEATURED IN") positioned above the grid -----
  const kickerTex = ctx.fontAtlas.getTexture('AS FEATURED IN', {
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 700,
    color: '#e8ecf2',
    opacity: 0.78,
    atlas: 0,
    rect: [0, 0, 512, 320],
    letterSpacing: 0.12,
    lineHeight: 1.2,
  });

  const kickerW = totalW * 0.9;
  const kickerH = 0.25;
  const kickerGeo = new THREE.PlaneGeometry(kickerW, kickerH);
  const kickerMat = new THREE.MeshBasicNodeMaterial();
  kickerMat.map = kickerTex;
  kickerMat.transparent = true;
  kickerMat.opacity = 0.78;

  const kickerMesh = new THREE.Mesh(kickerGeo, kickerMat);
  kickerMesh.position.set(0, startY + tileH / 2 + 0.3, 0.001);
  container.add(kickerMesh);
  cleanupResources.push(kickerGeo, kickerMat, kickerTex);

  // ----- staggered fade‑up animation on mount -----
  const mountTL = gsap.timeline();
  tiles.forEach((obj, i) => {
    const { tile, txtMat } = obj;
    // start offset
    tile.position.y += 0.2;
    // opacity already 0 for tile material; text material stays at final opacity
    mountTL
      .to(
        tile.position,
        { y: tile.position.y - 0.2, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        i * 0.08
      )
      .to(
        tile.material,
        { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        i * 0.08
      );
  });
  // kicker fade‑up as well
  kickerMesh.position.y += 0.2;
  kickerMat.opacity = 0;
  mountTL
    .to(
      kickerMesh.position,
      { y: kickerMesh.position.y - 0.2, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    )
    .to(kickerMat, { opacity: 0.78, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);

  // ----- cleanup ----------
  container.userData.cleanup = () => {
    // dispose geometries, materials, textures
    cleanupResources.forEach(res => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });
    // kill timelines
    mountTL.kill();
    tiles.forEach(o => {
      if (o.tile.userData._hoverTL) o.tile.userData._hoverTL.kill();
    });
    // clear references
    container.traverse(child => {
      child.userData = {};
    });
  };

  return container;
}
